import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import axios from "axios";

const API_URL = "https://productcode.tekit.in/pharmacy/";

export const addPharmacyForm = createAsyncThunk('addPharmacyForm', async(data, {rejectWithValue}) => {
    try{
        const response = await axios.post(API_URL + "add-pharmacy-form", data);
        if(response.data.status === true){
            return response.data;
            } else {
                return rejectWithValue(response.data.message);
            }
    }catch (err) {
        return rejectWithValue(err);
    }
})

export const getAllPharmacyForms = createAsyncThunk('getAllPharmacyForms', async(params, {rejectWithValue}) => {
    try {
        const response = await axios.get(API_URL + "get-all-pharmacy", {
            params: {
                page: params.page,
                limit: params.limit
            }
        });
        
        if(response.data.status === true) {
            return response.data;
        } else {
            return rejectWithValue(response.data.message);
        }
    } catch (err) {
        return rejectWithValue(err);
    }
})

export const updatePharmacyForms = createAsyncThunk('updateAllPharmacyForms', async(data, {rejectWithValue}) => {
    try{
        const response = await axios.put(API_URL + "update-pharmacy-form", data);
       
        if(response.data.status === true){
            
            return response.data;
            } else {
                return rejectWithValue(response.data.message);
            }
    }catch (err) {
        return rejectWithValue(err);
    }
})

export const getPharmacyFormsByDescription = createAsyncThunk('getPharmacyFormsByDescription', async(data, {rejectWithValue}) => {
    try{
        const response = await axios.get(API_URL + "get-pharmacy-forms-by-description/" + data); 
        if(response.data.status === true){
            return response.data;
        } else {
            return rejectWithValue(response.data.message);
        }
    }catch (err) {
        return rejectWithValue(err);
    }
})

const PharmacySlice = new createSlice({
    name : "Pharmacy",
    initialState : {
        isLoading: true,
        data: null,
        isError: false,
        message : "",
    },

    extraReducers  : (builder) => {
        builder.addCase(addPharmacyForm.pending, (state) => {
            state.isLoading = false;
        })
        builder.addCase(addPharmacyForm.fulfilled, (state, action) => {
            state.isLoading = false;
            state.data = action.payload;
        })
        builder.addCase(addPharmacyForm.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
        })


        builder.addCase(getAllPharmacyForms.pending, (state) => {
            state.isLoading = false;
        })
        builder.addCase(getAllPharmacyForms.fulfilled, (state, action) => {
            state.isLoading = false;
            state.data = action.payload;
        })
        builder.addCase(getAllPharmacyForms.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
        })


        builder.addCase(updatePharmacyForms.pending, (state) => {
            state.isLoading = false;
        })
        builder.addCase(updatePharmacyForms.fulfilled, (state, action) => {
            state.isLoading = false;
            state.data = action.payload;
        })
        builder.addCase(updatePharmacyForms.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
        })

        builder.addCase(getPharmacyFormsByDescription.pending, (state) => {
            state.isLoading = false;
        })
        builder.addCase(getPharmacyFormsByDescription.fulfilled, (state, action) => {
            state.isLoading = false;
            state.data = action.payload;
        })
        builder.addCase(getPharmacyFormsByDescription.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
        })
    }
})

export default PharmacySlice.reducer;