import {  createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import axios from "axios";
const API_URL = "https://productcode.tekit.in/company/";
// const API_URL = "https://productcode.tekit.in/company/";

export const addCompanyForm = createAsyncThunk('addComnpanyForm', async(data, {rejectWithValue}) => {
    try{

        const response = await axios.post(API_URL + "company-form", data);
        if(response.data.status === true){
            return response.data;
        } else {
            return rejectWithValue(response.data.message);
        }

    } catch (err) {
        return rejectWithValue(err);
    }
})

export const getAllCompanyForms = createAsyncThunk(
    'companyForm/getAllCompanyForms',
    async ({ page, limit } = { page: 1, limit: 15 }) => {
        try {
            const response = await axios.get(API_URL + `getall-company-form?page=${page}&limit=${limit}`);
            return response.data;
        } catch (error) {
            throw error;
        }
    }
);

export const updateCompanyFormStatus = createAsyncThunk('updateCompanyFormStatus', async(data, {rejectWithValue}) => {
    console.log("Slice data ", data);
    try{
        const response = await axios.put(API_URL + "update-approval-status", data);
        if(response.data.status === true){
            return response.data;
        } else {
            return rejectWithValue(response.data.message);
        }
    } catch (err) {
        return rejectWithValue(err);
    }
})

export const deleteCompanyForm = createAsyncThunk('deleteCompanyForm', async(data, {rejectWithValue}) => {
    console.log("delete data", data);
    try{
        const response = await axios.delete(API_URL + "delete-company-form/" + data._id);
        if(response.data.status === true){
            return response.data;
        } else {
            return rejectWithValue(response.data.message);
        }
    } catch (err) {
        return rejectWithValue(err);
    }
})

export const getCompanyFormsByDescription = createAsyncThunk(
    'getCompanyFormsByDescription', 
    async(description, {rejectWithValue}) => {
        try {
            const response = await axios.get(API_URL + "get-company-forms-by-description?description=" + description);
            return response.data;
        } catch (err) {
            return rejectWithValue(err);
        }
    }
)

const CompanyFormSlice = createSlice({
    name : "CompanyForm",
    initialState : {
        isLoading : true,
        data : null,
        isError : false,
        message : "",
        updateMessage : "",
        updateData : "",
        searchData: null,
    },
    extraReducers : (builder) => {
        builder.addCase(addCompanyForm.pending, (state) => {
            state.isLoading = true;
        })
        builder.addCase(addCompanyForm.fulfilled, (state, action) => {
            state.isError = false;
            state.isLoading = false;
            state.data = action.payload;
        })
        builder.addCase(addCompanyForm.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
            state.message =  "Error"
        })


        builder.addCase(getAllCompanyForms.pending, (state) => {
            state.isLoading = true;
        })
        builder.addCase(getAllCompanyForms.fulfilled, (state, action) => {
            state.isError = false;
            state.isLoading = false;
            state.data = action.payload;
        })
        builder.addCase(getAllCompanyForms.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
            state.message =  "Error"
        })

        builder.addCase(updateCompanyFormStatus.pending, (state) => {
            state.isLoading = true;
        })
        builder.addCase(updateCompanyFormStatus.fulfilled, (state, action) => {
            state.isError = false;
            state.isLoading = false;
            state.updateData = action.payload;
        })
        builder.addCase(updateCompanyFormStatus.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
            state.updateMessage =  "Error"
        })

        builder.addCase(deleteCompanyForm.pending, (state) => {
            state.isLoading = true;
        })
        builder.addCase(deleteCompanyForm.fulfilled, (state, action) => {
            state.isError = false;
            state.isLoading = false;
            state.deleteData = action.payload;
        })
        builder.addCase(deleteCompanyForm.rejected, (state) => {
            state.isError = true;
            state.isLoading = false;
            state.deleteMessage =  "Error"
        })

        builder.addCase(getCompanyFormsByDescription.pending, (state) => {
            state.isLoading = true;
        })
        builder.addCase(getCompanyFormsByDescription.fulfilled, (state, action) => {
            state.isError = false;
            state.isLoading = false;
            state.searchData = action.payload.data;
        })
        builder.addCase(getCompanyFormsByDescription.rejected, (state, action) => {
            state.isError = true;
            state.isLoading = false;
            state.message = action.payload?.message || "Error in search";
        })
    }
})


export default CompanyFormSlice.reducer;
